export type Job<T> = () => Promise<T>;

export class JobQueue {
  private readonly concurrency: number;
  private readonly retries: number;
  private pending: Array<() => void> = [];
  private active = 0;
  private idleWaiters: Array<() => void> = [];

  constructor(concurrency: number, retries = 3) {
    if (!Number.isInteger(concurrency) || concurrency < 1) {
      throw new RangeError("concurrency must be a positive integer");
    }
    this.concurrency = concurrency;
    this.retries = retries;
  }

  /** Resolves with the job's result, or rejects with its last error once retries are exhausted. */
  add<T>(job: Job<T>): Promise<T> {
    return new Promise<T>((resolve, reject) => {
      this.pending.push(() => {
        this.attempt(job)
          .then(resolve, reject)
          .finally(() => {
            this.active--;
            this.next();
          });
      });
      this.next();
    });
  }

  /** Resolves when nothing is running or waiting. Never rejects; job errors surface via add(). */
  onIdle(): Promise<void> {
    if (this.active === 0 && this.pending.length === 0) return Promise.resolve();
    return new Promise((resolve) => this.idleWaiters.push(resolve));
  }

  private async attempt<T>(job: Job<T>): Promise<T> {
    // ponytail: retries fire immediately, add backoff/jitter here if jobs hit rate-limited services
    for (let failures = 0; ; failures++) {
      try {
        return await job();
      } catch (err) {
        if (failures >= this.retries) throw err;
      }
    }
  }

  private next(): void {
    while (this.active < this.concurrency && this.pending.length > 0) {
      this.active++;
      this.pending.shift()!();
    }
    if (this.active === 0 && this.pending.length === 0) {
      for (const resolve of this.idleWaiters.splice(0)) resolve();
    }
  }
}

import assert from "node:assert/strict";
import { JobQueue } from "./queue.ts";

const sleep = (ms: number) => new Promise((r) => setTimeout(r, ms));

// concurrency limit + onIdle
{
  const q = new JobQueue(2);
  let running = 0, peak = 0, done = 0;
  for (let i = 0; i < 6; i++) {
    q.add(async () => {
      peak = Math.max(peak, ++running);
      await sleep(10);
      running--;
      done++;
    });
  }
  await q.onIdle();
  assert.equal(peak, 2);
  assert.equal(done, 6);
  await q.onIdle(); // already idle: resolves immediately
}

// succeeds on the last allowed attempt (1 try + 3 retries)
{
  const q = new JobQueue(1);
  let calls = 0;
  const result = await q.add(async () => {
    if (++calls < 4) throw new Error("flaky");
    return "ok";
  });
  assert.equal(result, "ok");
  assert.equal(calls, 4);
}

// gives up after 3 retries, rejects with the last error, queue keeps working
{
  const q = new JobQueue(1);
  let calls = 0;
  const failed = q.add(async () => {
    throw new Error(`fail ${++calls}`);
  });
  const after = q.add(async () => "next");
  await assert.rejects(failed, /fail 4/);
  assert.equal(calls, 4);
  assert.equal(await after, "next");
  await q.onIdle();
}

console.log("ok");

